<template>
  <div class="cond-group" :class="{ 'cond-group--nested': nested }">
    <div class="cond-group-h">
      <span>{{ $t('if') }}</span>
      <q-select
        outlined dense emit-value map-options
        class="back-white cond-join"
        :model-value="group.join"
        :options="[{ label: $t('all'), value: 'all' }, { label: $t('any'), value: 'any' }]"
        @update:model-value="group.join = $event"
      />
      <span>{{ $t('of_following_true') }}</span>
      <q-space />
      <button v-if="nested && !readonly" type="button" class="cond-x" @click="$emit('remove')">✕</button>
    </div>

    <template v-for="(item, idx) in group.conditions" :key="idx">
      <!-- Nested group -->
      <ConditionGroup
        v-if="item.kind === 'group'"
        :group="item"
        nested
        :field-options="fieldOptions"
        :op-options="opOptions"
        :origin-options="originOptions"
        :sub-org-options="subOrgOptions"
        :lov-options="lovOptions"
        :readonly="readonly"
        @remove="removeItem(idx)"
      />

      <!-- Leaf condition -->
      <div v-else class="cond-row">
        <!-- Field cell: a raw JSON path input (Advanced) or the field picker. -->
        <q-input
          v-if="item.isPath"
          outlined dense
          class="back-white rb-mono cond-path"
          v-model="item.field"
          :placeholder="$t('json_path_placeholder')"
          :readonly="readonly"
        >
          <template #prepend>
            <span class="cond-path-badge">$path</span>
          </template>
        </q-input>
        <q-select
          v-else
          outlined dense use-input input-debounce="0" emit-value map-options
          class="back-white"
          :model-value="item.field"
          :options="localOptions[idx] || fieldOptions"
          :readonly="readonly"
          @filter="(val, update) => onFilter(idx, val, update)"
          @update:model-value="(val) => onFieldPick(item, idx, val)"
          :placeholder="item.field ? '' : $t('field')"
          popup-content-class="rb-field-popup"
        >
          <template #option="scope">
            <!-- One keyed root per option, group label nested inside it (shown
                 on the first option of each group) so it can't duplicate on scroll. -->
            <div :key="scope.opt.value">
              <div
                v-if="scope.opt.group && scope.opt.group !== (localOptions[idx] || fieldOptions)[scope.index - 1]?.group"
                class="rb-opt-group"
                :class="{ 'rb-opt-group--first': scope.index === 0 }"
              >{{ scope.opt.group }}</div>
              <q-item v-bind="scope.itemProps"><q-item-section>{{ scope.opt.label }}</q-item-section></q-item>
            </div>
          </template>
        </q-select>
        <q-select
          outlined dense emit-value map-options
          class="back-white"
          v-model="item.op"
          :options="operatorOptionsFor(item)"
          :readonly="readonly"
        />
        <!-- Value cell. Presence-only operators (is empty / is not empty) take no
             value → empty grid cell. Fields backed by a fixed/loaded vocabulary
             (doc.* enums) or booleans → dropdown; number types → numeric input;
             everything else → free-text. -->
        <template v-if="opNeedsValue(item.op)">
          <q-select
            v-if="rowValueOptions(item)"
            outlined dense use-input input-debounce="0" emit-value map-options
            class="back-white"
            :model-value="item.value"
            :options="localValueOptions[idx] || rowValueOptions(item) || []"
            :readonly="readonly"
            @filter="(val, update) => onValueFilter(idx, item, val, update)"
            @update:model-value="(val) => (item.value = val)"
            :placeholder="item.value ? '' : $t('value')"
          />
          <q-input
            v-else
            outlined dense
            :type="isNumericRow(item) ? 'number' : 'text'"
            class="back-white"
            v-model="item.value"
            :placeholder="item.op === 'in' ? $t('comma_separated') : $t('value')"
            :readonly="readonly"
          />
        </template>
        <span v-else aria-hidden="true" />
        <!-- Case-insensitive toggle: shown only for text-comparison operators
             (the backend case-folds just those); disabled but still visible in
             read-only mode so the setting stays legible. -->
        <button
          v-if="supportsCaseInsensitive(item.op)"
          type="button"
          class="cond-ci"
          :class="{ 'cond-ci--on': item.case_insensitive }"
          :disabled="readonly || !caseInsensitiveApplies(item)"
          :aria-pressed="item.case_insensitive"
          @click="item.case_insensitive = !item.case_insensitive"
        >
          Aa
          <q-tooltip>{{ $t('case_insensitive') }}</q-tooltip>
        </button>
        <span v-else aria-hidden="true" />
        <button v-if="!readonly" type="button" class="cond-x" @click="removeItem(idx)">✕</button>
      </div>
    </template>

    <div v-if="!readonly" class="add-links">
      <button type="button" @click="addCondition">+ {{ $t('add_condition') }}</button>
      <!-- Sub-groups are always offered: every builder embedding this editor
           serializes, parses and evaluates the nested tree, so there is no
           consumer that has to hide the affordance. -->
      <button type="button" @click="addGroup">+ {{ $t('add_nested_group') }}</button>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import type { PropType } from 'vue';
import {
  newCondition,
  newGroup,
  CUSTOM_PATH_OPTION,
  PATH_OP_OPTIONS,
  NO_VALUE_OPS,
  opSupportsCaseInsensitive,
  operatorsForField,
  isNumericFieldType,
  fieldTypeSupportsCaseInsensitive,
  valueOptionsForField,
  docStatusValueOptions,
  DOC_STATUS_FIELD,
  BOOLEAN_VALUE_OPTIONS,
  type BuilderCondition,
  type BuilderGroup,
  type ConditionOp,
  type FieldOption,
} from './rule-builder-model';

export default defineComponent({
  name: 'ConditionGroup',
  props: {
    group: {
      type: Object as PropType<BuilderGroup>,
      required: true,
    },
    nested: {
      type: Boolean,
      default: false,
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    fieldOptions: {
      type: Array as PropType<FieldOption[]>,
      default: () => [],
    },
    opOptions: {
      type: Array as PropType<{ label: string; value: ConditionOp }[]>,
      default: () => [],
    },
    // Value options for the doc.doc_origin picker, loaded once by the parent
    // and threaded down through nested groups.
    originOptions: {
      type: Array as PropType<FieldOption[]>,
      default: () => [],
    },
    // Value options for the doc.sub_org_id picker, same threading as origins.
    subOrgOptions: {
      type: Array as PropType<FieldOption[]>,
      default: () => [],
    },
    // Values of every list-of-values referenced by the field options, keyed by
    // list name (loadLovValueOptions), so a LOV-backed header field offers its
    // allowed values instead of a free-text box.
    lovOptions: {
      type: Object as PropType<Record<string, FieldOption[]>>,
      default: () => ({}),
    },
  },
  emits: ['remove'],
  data() {
    return {
      // Per-row filtered copies of the field list, keyed by condition index, so
      // filtering one leaf's select never disturbs another's options.
      localOptions: {} as Record<number, FieldOption[]>,
      // Same per-row isolation for the VALUE dropdown (doc.* controlled fields),
      // so typing in one row's value picker never mutates another's options.
      localValueOptions: {} as Record<number, FieldOption[]>,
      // Narrowed operator set for Custom JSON path rows.
      pathOpOptions: PATH_OP_OPTIONS,
    };
  },
  computed: {
    // Status labels use the same Tolgee keys as the documents list; the stored
    // value stays the raw status key.
    statusValueOptions(): FieldOption[] {
      return docStatusValueOptions().map((o) => ({ ...o, label: this.$t(o.value) }));
    },
  },
  methods: {
    // Presence-only operators (is not empty) take no comparison value, so the
    // value textbox is hidden for them.
    opNeedsValue(op: ConditionOp): boolean {
      return !NO_VALUE_OPS.includes(op);
    },
    // Whether this operator offers the case-insensitive toggle (text ops only).
    supportsCaseInsensitive(op: ConditionOp): boolean {
      return opSupportsCaseInsensitive(op);
    },
    // Case-insensitivity is meaningless for number/boolean values, so the toggle
    // is shown (for the operator) but disabled for those field types.
    caseInsensitiveApplies(item: BuilderCondition): boolean {
      return fieldTypeSupportsCaseInsensitive(this.fieldType(item.field));
    },
    // The declared type of a picked field (from the field option), or undefined
    // for a raw JSON path / unmapped field → treated as free text.
    fieldType(field: string): string | undefined {
      return this.fieldOptions.find((o) => o.value === field)?.type;
    },
    // Operators offered for a row: the narrow JSON-path set for path rows,
    // otherwise the set implied by the selected field's type.
    operatorOptionsFor(item: BuilderCondition): { label: string; value: ConditionOp }[] {
      return item.isPath ? this.pathOpOptions : operatorsForField(this.fieldType(item.field));
    },
    // The list-of-values name behind a picked field, when it is LOV-backed.
    fieldLov(field: string): string | undefined {
      return this.fieldOptions.find((o) => o.value === field)?.lov;
    },
    // Value options for a row: booleans → true/false; doc.* enums and
    // LOV-backed fields → their loaded lists; everything else → null
    // (free-text / numeric input).
    rowValueOptions(item: BuilderCondition): FieldOption[] | null {
      if ((this.fieldType(item.field) || '').toUpperCase() === 'BOOLEAN') return BOOLEAN_VALUE_OPTIONS;
      if (item.field === DOC_STATUS_FIELD) return this.statusValueOptions;
      const lov = this.fieldLov(item.field);
      if (lov && this.lovOptions[lov]?.length) return this.lovOptions[lov];
      return valueOptionsForField(item.field, this.originOptions, this.subOrgOptions);
    },
    // A numeric field with no dropdown → render a number input.
    isNumericRow(item: BuilderCondition): boolean {
      return isNumericFieldType(this.fieldType(item.field)) && !this.rowValueOptions(item);
    },
    // Filter this row's VALUE dropdown locally against its field's option set.
    // Own copy per row so filtering one row never disturbs another's options.
    onValueFilter(idx: number, item: BuilderCondition, val: string, update: (cb: () => void) => void) {
      const base: FieldOption[] = this.rowValueOptions(item) || [];
      update(() => {
        const needle = val.toLowerCase();
        this.localValueOptions[idx] = needle
          ? base.filter((o) => o.label.toLowerCase().includes(needle) || o.value.toLowerCase().includes(needle))
          : base.slice();
      });
    },
    addCondition() {
      this.group.conditions.push(newCondition());
    },
    // Field picker changed. Choosing the "Custom JSON path" sentinel flips the
    // row into raw-path mode (a `$path` text input) rather than storing it as a
    // field; any other value is a normal mapped-field selection.
    onFieldPick(item: BuilderCondition, idx: number, val: string) {
      if (val === CUSTOM_PATH_OPTION) {
        item.isPath = true;
        item.field = '';
        // The path operator set is narrower; fall back to "is" if the current
        // op (e.g. greater than) isn't offered for paths.
        if (!this.pathOpOptions.some((o) => o.value === item.op)) {
          item.op = 'eq';
        }
      } else {
        item.field = val;
        // The new field's type may not allow the current operator (e.g. switching
        // a text field to a number drops contains/starts_with). Fall back to the
        // first allowed operator when the current one is no longer offered.
        const allowed = operatorsForField(this.fieldType(val)).map((o) => o.value);
        if (!allowed.includes(item.op)) item.op = allowed[0];
        // Number/boolean fields ignore case — clear any stale flag so it can't
        // serialize on a field where it means nothing.
        if (!this.caseInsensitiveApplies(item)) item.case_insensitive = false;
      }
      // The value picker's vocabulary depends on the field. Switching fields can
      // flip a free-text value into a dropdown (or between doc vocabularies), so
      // reset the old value and drop this row's stale filtered value options.
      item.value = '';
      delete this.localValueOptions[idx];
    },
    addGroup() {
      this.group.conditions.push(newGroup('all'));
    },
    removeItem(idx: number) {
      this.group.conditions.splice(idx, 1);
      // Row indices shift after a splice — drop the per-row filter state so the
      // remaining selects fall back to the full list rather than a stale copy.
      this.localOptions = {};
      this.localValueOptions = {};
    },
    // Filter this row's list locally against the shared source. Always a fresh
    // array, scoped to this row so filtering one leaf never touches another.
    onFilter(idx: number, val: string, update: (cb: () => void) => void) {
      update(() => {
        const needle = val.toLowerCase();
        this.localOptions[idx] = needle
          ? this.fieldOptions.filter((f) => f.label.toLowerCase().includes(needle) || f.value.toLowerCase().includes(needle))
          : this.fieldOptions.slice();
      });
    },
  },
});
</script>

<style scoped lang="scss">
.cond-group {
  border: 1px dashed #bcc9d4;
  border-radius: 9px;
  padding: 12px;
  background: #fafcfc;
}

.cond-group--nested {
  margin: 8px 0 8px 12px;
}

.cond-group-h {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  color: #6b7280;
  margin-bottom: 10px;
}

.cond-join {
  width: auto;
  min-width: 88px;
}

// Grid keeps the row aligned: three fields + a case-insensitive toggle + a
// fixed remove column. No overflow, no flex-shrink juggling.
.cond-row {
  display: grid;
  grid-template-columns: minmax(170px, 1.2fr) minmax(130px, 0.9fr) minmax(120px, 1fr) 28px 28px;
  gap: 8px;
  margin-bottom: 8px;
  align-items: center;
}

@media (max-width: 720px) {
  .cond-row {
    grid-template-columns: 1fr 1fr;
    grid-auto-rows: auto;
  }
}

// Custom JSON path input — the "$path" prefix badge marks the row as a raw
// path rather than a mapped field.
.cond-path-badge {
  font-family: 'Roboto Mono', ui-monospace, monospace;
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  padding-right: 2px;
}

.cond-path :deep(input) {
  font-family: 'Roboto Mono', ui-monospace, monospace;
  font-size: 0.8125rem;
}

.cond-x {
  border: none;
  background: none;
  color: #9aa8b4;
  font-size: 15px;
  line-height: 1;
  cursor: pointer;
  padding: 0;

  &:hover { color: var(--q-negative); }
}

// Case-insensitive toggle — a compact "Aa" button that fills its grid cell,
// tinted with the primary colour when active.
.cond-ci {
  height: 28px;
  border: 1px solid #d4dde5;
  border-radius: 6px;
  background: #fff;
  color: #6b7280;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;

  &:hover:not(:disabled) {
    border-color: var(--q-primary);
    color: var(--q-primary);
  }

  &:disabled { cursor: default; opacity: 0.6; }
}

.cond-ci--on {
  background: var(--q-primary);
  border-color: var(--q-primary);
  color: #fff;

  &:hover:not(:disabled) { color: #fff; }
}

.add-links {
  display: flex;
  gap: 16px;
  margin-top: 4px;

  button {
    border: none;
    background: none;
    color: var(--q-primary);
    font-weight: 600;
    font-size: 12.5px;
    cursor: pointer;
    padding: 2px 0;
  }
}

body.body--dark {
  .cond-group {
    border-color: rgba(255, 255, 255, 0.14);
    background: rgba(255, 255, 255, 0.03);
  }
  .cond-group-h { color: #94a3b8; }
  .cond-path-badge { color: #94a3b8; }
  .cond-ci {
    border-color: rgba(255, 255, 255, 0.18);
    background: rgba(255, 255, 255, 0.04);
    color: #94a3b8;
  }
  .cond-ci--on {
    background: var(--q-primary);
    border-color: var(--q-primary);
    color: #fff;
  }
}
</style>

